# (b) Chronology: the vote fell (November 1932) only AFTER the breakthrough (July 1932).
def chronology(fall_year: int = 1932, fall_month: int = 11) -> dict:
    return {
        "problem": {
            "problem_id": "hist-chronology", "request_id": "REQ", "claim_id": "CLAIM", "query": "entailment",
            "symbols": [{"name": "breakthrough_month", "sort": "Int", "meaning": "July 1932 as year*12+month"}, {"name": "fall_month", "sort": "Int", "meaning": "the month the vote fell"}],
            "premises": [
                {"id": "BREAK", "expr": _cmp("eq", _v("breakthrough_month"), _i(_month(1932, 7))), "label": "largest party in July 1932", "grounding": MEMORY},
                {"id": "FALL", "expr": _cmp("eq", _v("fall_month"), _i(_month(fall_year, fall_month))), "label": f"vote fell in {fall_month}/{fall_year}", "grounding": MEMORY},
            ],
            "conclusion": {"id": "AFTER", "expr": _cmp("gt", _v("fall_month"), _v("breakthrough_month")), "label": "the fall came only after the breakthrough"},
        },
        "interpretation": {"reading": "Ordering of two dated events.", "glossary": [], "ambiguity_flags": []}, "ambiguous": False, "unsupported_reason": None,
    }

CHRONOLOGY_OK = chronology()
CHRONOLOGY_ERROR = chronology(1931, 11)

